head.script:
scwin.onpageload = function() {
    requires("uiplugin.popup");
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "500px",
        height: "500px"
    };
    $p.openPopup("selectbox_gridviewitemset_WEFF-917_(WSQ-4410)_popup.xml", options);
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('popup1_wframe_selectbox1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'popup1_wframe_selectbox1_gridViewItemTable').style.getPropertyValue('z-index') == '6210'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
